async function loadAlertEvaluationData(tx2, userId, now) {
  const month = localDate(now).slice(0, 7);
  const accountRows = await tx2.select({
    id: accounts.id,
    name: accounts.name,
    type: accounts.type,
    balanceCents: accounts.balanceCents
  }).from(accounts).where(eq(accounts.userId, userId));
  const recurrenceRows = await tx2.select({
    id: recurrences.id,
    kind: recurrences.kind,
    label: recurrences.label,
    status: recurrences.status,
    expectedAmountCents: recurrences.expectedAmountCents,
    previousAmountCents: recurrences.previousAmountCents,
    nextExpectedDate: recurrences.nextExpectedDate,
    accountType: accounts.type
  }).from(recurrences).leftJoin(accounts, and(eq(accounts.id, recurrences.accountId), eq(accounts.userId, userId))).where(eq(recurrences.userId, userId));
  const billRows = await tx2.select({
    id: bills.id,
    accountId: bills.accountId,
    accountName: accounts.name,
    dueDate: bills.dueDate,
    totalCents: bills.totalCents,
    paidCents: bills.paidCents
  }).from(bills).innerJoin(accounts, and(eq(accounts.id, bills.accountId), eq(accounts.userId, userId))).where(eq(bills.userId, userId));
  const transactionRows = await tx2.select({
    ...getTableColumns(transactions),
    accountName: accounts.name,
    accountType: accounts.type,
    categoryName: categories.name,
    categoryKind: categories.kind
  }).from(transactions).innerJoin(accounts, and(eq(accounts.id, transactions.accountId), eq(accounts.userId, userId))).innerJoin(categories, and(eq(categories.id, transactions.categoryId), or(isNull(categories.userId), eq(categories.userId, userId)))).where(eq(transactions.userId, userId));
  const budgetRows = await tx2.select({
    categoryId: budgets.categoryId,
    limitCents: budgets.limitCents
  }).from(budgets).where(and(eq(budgets.userId, userId), eq(budgets.month, month)));
  const connectionRows = await tx2.select({
    id: connections.id,
    institutionName: connections.institutionName,
    status: connections.status,
    consentExpiresAt: connections.consentExpiresAt
  }).from(connections).where(eq(connections.userId, userId));
  return {
    accounts: accountRows,
    transactions: transactionRows,
    recurrences: recurrenceRows,
    bills: billRows,
    budgets: budgetRows,
    connections: connectionRows
  };
}
async function runAlertEvaluationInTransaction(tx2, userId, now) {
  const data = await loadAlertEvaluationData(tx2, userId, now);
  const candidates = evaluateAlerts(data, now);
  if (!candidates.length) return 0;
  const preferenceRows = await tx2.select({
    type: alertPreferences.type,
    enabled: alertPreferences.enabled
  }).from(alertPreferences).where(eq(alertPreferences.userId, userId));
  const preferences = Object.fromEntries(
    ALERT_PREFERENCE_TYPES.map((type) => [type, true])
  );
  for (const preference of preferenceRows) {
    if (ALERT_PREFERENCE_TYPES.includes(preference.type)) {
      preferences[preference.type] = preference.enabled;
    }
  }
  const candidateKeys = [...new Set(candidates.map((candidate) => candidate.dedupeKey))];
  const existingRows = await tx2.select({ dedupeKey: alerts.dedupeKey }).from(alerts).where(and(eq(alerts.userId, userId), inArray(alerts.dedupeKey, candidateKeys)));
  const { start, end } = alertInfoWeekBounds(now);
  const [weeklyInfoCount] = await tx2.select({ value: count() }).from(alerts).where(and(
    eq(alerts.userId, userId),
    eq(alerts.severity, "info"),
    ne(alerts.type, "weekly_summary"),
    gte(alerts.createdAt, start),
    lt(alerts.createdAt, end)
  ));
  const selected = selectAlertDrafts(
    candidates,
    preferences,
    new Set(existingRows.map((row) => row.dedupeKey)),
    weeklyInfoCount?.value ?? 0
  );
  let inserted = 0;
  for (const alert of selected) {
    const rows = await tx2.insert(alerts).values({
      ...alert,
      userId,
      createdAt: now,
      updatedAt: now
    }).onConflictDoNothing().returning({ id: alerts.id });
    inserted += rows.length;
  }
  return inserted;
}
async function evaluateUserAlerts(userId, now) {
  return db.transaction(async (tx2) => {
    await tx2.execute(sql`select pg_advisory_xact_lock(hashtextextended(${userId}, 0))`);
    return runAlertEvaluationInTransaction(tx2, userId, now);
  });
}
async function evaluateAlertsForAllUsers(now) {
  const userRows = await db.select({ id: users.id }).from(users);
  for (const user of userRows) {
    try {
      await evaluateUserAlerts(user.id, now);
    } catch {
      logger.warn("Daily alert evaluation failed for a user");
    }
  }
}

// jobs/post-sync.ts
async function runPostSyncPipeline(context) {
  await runCategorization(context.tx, context.userId, context.now, context.classify);
  await runFinancialRules(context.tx, context.userId, context.now);
  await runAlertEvaluationInTransaction(context.tx, context.userId, context.now);
}

